const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const longBeach = ee.Geometry.Point([-118.089042, 33.601421]);
  const pismoBeach = ee.Geometry.Point([-120.727924, 35.128348]);
  const date = '2018-08-02';

  // 2. Data Acquisition & Check
  // NOAA OISST provides daily sea surface temperature (SST) and includes a pre-calculated 'anomaly' band.
  // The anomaly is the difference between the measured SST and the long-term mean.
  const sstCollection = ee.ImageCollection('NOAA/CDR/OISST/V2.1')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .select('anomaly');

  const imageCount = sstCollection.size().getInfo();
  if (imageCount === 0) {
    console.log(`No images found for date: ${date}`);
    console.log('A'); // This should be C1, but the prompt says to use A/B tags.
    return;
  }

  const sstImage = sstCollection.first();

  // 3. Processing & Calculation
  // The dataset scale is ~5km. Using a similar scale for extraction.
  const scale = 5000;

  // Extract anomaly at Long Beach
  const anomalyLongBeachDict = sstImage.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: longBeach,
    scale: scale,
    maxPixels: 1
  });

  // Extract anomaly at Pismo Beach
  const anomalyPismoBeachDict = sstImage.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: pismoBeach,
    scale: scale,
    maxPixels: 1
  });

  const anomalyLongBeach = anomalyLongBeachDict.get('anomaly').getInfo();
  const anomalyPismoBeach = anomalyPismoBeachDict.get('anomaly').getInfo();

  // 4. Validation & Final Answer
  console.log(`Image found for ${date}: Yes`);

  if (anomalyLongBeach === null || anomalyPismoBeach === null) {
    console.log('Could not extract valid temperature anomaly at one or both locations.');
    console.log(`Long Beach Value: ${anomalyLongBeach}`);
    console.log(`Pismo Beach Value: ${anomalyPismoBeach}`);
    console.log('C3');
    return;
  }

  console.log(`Long Beach SST Anomaly (C): ${anomalyLongBeach.toFixed(2)}`);
  console.log(`Pismo Beach SST Anomaly (C): ${anomalyPismoBeach.toFixed(2)}`);

  const isHigher = anomalyLongBeach > anomalyPismoBeach;
  console.log(`Was Long Beach anomaly higher than Pismo Beach?: ${isHigher}`);

  if (isHigher) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
});
